(function(){
  'use strict';
  const $=id=>document.getElementById(id),D=window.LumenData,E=window.LumenEngine;
  const storageKey='lumen-quest-v1';
  let profile=E.blankProfile(),storageAvailable=true;
  try{profile=E.sanitizeProfile(JSON.parse(localStorage.getItem(storageKey)));}catch{storageAvailable=false;}
  let session=null,duration=5,modalKind='',sound=false,audio=null,toastTimer=0,finished=false,lastTime=performance.now();
  const world=new window.LumenWorld($('world'));
  world.hero=D.heroes.find(h=>h.id===profile.selected);
  const esc=text=>String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const selectedHero=()=>D.heroes.find(h=>h.id===profile.selected)||D.heroes[0];
  const spriteStyle=h=>`background-position:${h.cell%4*100/3}% ${Math.floor(h.cell/4)*100}%;`;
  function save(){try{localStorage.setItem(storageKey,JSON.stringify(profile));}catch{storageAvailable=false;}}
  function announce(text){$('announcement').textContent=text;}
  function toast(text){clearTimeout(toastTimer);$('worldToast').textContent=text;$('worldToast').classList.add('show');announce(text);toastTimer=setTimeout(()=>$('worldToast').classList.remove('show'),2700);}
  function tone(good=true){if(!sound)return;try{if(!audio)audio=new (window.AudioContext||window.webkitAudioContext)();audio.resume();const now=audio.currentTime;const notes=good?[523.25,659.25,783.99]:[261.63,207.65];notes.forEach((f,i)=>{const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=f;g.gain.setValueAtTime(0,now+i*.09);g.gain.linearRampToValueAtTime(.07,now+i*.09+.02);g.gain.exponentialRampToValueAtTime(.001,now+i*.09+.22);o.connect(g);g.connect(audio.destination);o.start(now+i*.09);o.stop(now+i*.09+.23);});}catch{sound=false;$('soundButton').classList.remove('on');}}
  function shell(eyebrow,title,body,closable=true){return `<div class="modal-shell"><div class="modal-header"><div><span class="eyebrow">${eyebrow}</span><h2>${title}</h2></div>${closable?'<button class="close-modal" data-action="close" aria-label="Close dialog">×</button>':''}</div>${body}</div>`;}
  function openModal(kind,content){modalKind=kind;world.keys.clear();if(session?.active)session.paused=true;$('modalContent').innerHTML=content;if(!$('modal').open)$('modal').showModal();world.blocked=true;const focusable=$('modalContent').querySelector('button:not(:disabled)');if(focusable)focusable.focus();}
  function dismissModal(){modalKind='';$('modal').close();if(session?.active)session.paused=false;lastTime=performance.now();world.blocked=!session?.canFight;world.keys.clear();$('world').focus({preventScroll:true});}
  function closeModal(){if(modalKind==='quiz'||modalKind==='levelComplete'){announce('Finish this question or choose an option to continue.');return;}dismissModal();}
  $('modal').addEventListener('cancel',event=>{event.preventDefault();closeModal();});
  $('modal').addEventListener('click',event=>{if(event.target===$('modal')){const r=$('modal').getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal();}});

  function updateUI(){
    const h=selectedHero();$('coins').textContent=profile.coins.toLocaleString();$('heroCount').textContent=profile.owned.length+'/8';$('hudPortrait').style.cssText=spriteStyle(h);$('hudName').textContent=h.name;world.hero=h;world.compass=profile.items.includes('wisdom-compass');$('leaderName').textContent=profile.name||'You, the explorer';
    if(session){$('timer').textContent=formatTime(session.remaining);$('timeFill').style.width=(session.remaining/session.duration*100)+'%';$('lives').innerHTML=session.lives+' <small>/ 5</small>';$('answered').textContent=session.answered;$('streak').innerHTML=session.streak+' <span class="amber">✦</span>';$('score').textContent=session.score.toLocaleString();$('healthFill').style.width=(session.health/h.hp*100)+'%';$('healthText').textContent=session.hp+' / '+h.hp+' HP';$('hudLives').textContent='♥ '.repeat(session.lives)+'♡ '.repeat(5-session.lives);$('timer').style.color=session.remaining<30?'#f0ad98':'';
      $('areaName').textContent=session.level.name.toUpperCase();$('levelProgress').textContent=session.levelDefeated+' / '+session.level.enemies+' enemies';$('difficultyLabel').textContent=session.level.difficulty;$('levelNumber').textContent='AREA '+(session.levelIndex+1)+' / 5';$('levelFill').style.width=(session.levelDefeated/session.level.enemies*100)+'%';
    }
  }
  function formatTime(seconds){return `${Math.floor(Math.ceil(seconds)/60).toString().padStart(2,'0')}:${(Math.ceil(seconds)%60).toString().padStart(2,'0')}`;}
  function renderTeasers(){const picks=[D.heroes[0],D.heroes[2],D.heroes[4],D.heroes[6]];$('heroTeasers').innerHTML=picks.map(h=>`<button class="teaser" data-hero="${h.id}" style="--aura:${h.color}"><span class="sprite" style="${spriteStyle(h)}"></span><span><b>${h.name}</b><small>${h.rarity}</small></span></button>`).join('');}
  $('heroTeasers').addEventListener('click',event=>{if(event.target.closest('[data-hero]'))showHeroes();});
  document.querySelectorAll('[data-duration]').forEach(button=>button.addEventListener('click',()=>{if(session?.active)return;duration=Number(button.dataset.duration);document.querySelectorAll('[data-duration]').forEach(b=>b.classList.toggle('selected',b===button));$('timer').textContent=formatTime(duration*60);}));

  function start(){
    if(session?.active)return;profile.name=$('playerName').value.trim().slice(0,20)||'Curious Explorer';save();session=new E.Session(duration,selectedHero());finished=false;lastTime=performance.now();world.start(session);world.blocked=false;
    $('welcome').hidden=true;$('heroHud').hidden=false;$('pauseButton').hidden=false;$('touchControls').hidden=false;$('sessionBadge').textContent='LIVE';$('expeditionTitle').textContent='Face the temptation.';$('expeditionDescription').textContent='Fight an enemy. Answer its question. Keep your values.';$('pageTitle').textContent='Five realms. A stronger sense of choice.';$('adventureStatus').textContent='Walk, run, jump · J to attack';$('playerName').disabled=true;document.querySelectorAll('[data-duration]').forEach(b=>b.disabled=true);$('worldCaption').textContent='Approach an enemy and press J to attack. Jump to dodge.';if($('modal').open)dismissModal();updateUI();tone();toast('Lantern Meadow · Super Easy. Hold J to attack.');$('world').focus({preventScroll:true});
  }
  function showQuiz(){
    if(!session?.active||session.phase!=='quiz')return;const q=session.question;
    openModal('quiz',shell('ENEMY DEFEATED · GAME PAUSED','One victory. One important choice.',`<div class="quiz-meta"><span>${esc(q.subject)}</span> AREA ${session.levelIndex+1}<span>+40–60 GOLD</span></div><h3 class="quiz-question">${esc(q.text)}</h3><div class="answer-grid">${session.answers.map((a,i)=>`<button class="answer-option" data-answer="${i}"><span>${'ABCD'[i]}</span>${esc(a.text)}</button>`).join('')}</div><div id="feedback"></div><div class="quiz-footer"><span>Action & timer paused · keys 1–4 also work</span><span>${session.lives} quiz chances left</span></div>`,false));
  }
  function answer(index){
    const result=session?.answer(index);if(!result)return;profile.coins+=result.gold;save();updateUI();tone(result.correct);world.effect(result.correct);
    $('modalContent').querySelectorAll('[data-answer]').forEach((b,i)=>{b.disabled=true;if(i===result.correctIndex)b.classList.add('correct');if(i===index&&!result.correct)b.classList.add('wrong');});
    const source=session.question.source?`<a class="question-source" href="${esc(session.question.source)}" target="_blank" rel="noopener noreferrer">Read the source ↗</a>`:'';
    $('feedback').innerHTML=`<div class="quiz-feedback ${result.correct?'':'wrong'}" role="status"><h3>${result.correct?'✦ A thoughtful choice!':'A wrong turn. A useful lesson.'}</h3><p>${esc(result.explanation)}</p>${source}<p class="feedback-reward">${result.correct?`+${result.gold} gold · +15 health (up to maximum)`:'One quiz chance used. Your defeated enemy stays defeated.'}</p>${session.active?'<div class="feedback-countdown"><strong id="returnCountdown">Returning in 2 seconds…</strong><button class="secondary" data-action="read-more">Keep reading</button></div>':'<button class="primary" data-action="continue">See your journey →</button>'}</div>`;
    $('feedback').querySelector('button').focus();announce((result.correct?'Correct. ':'Incorrect. ')+result.explanation);if(session.active){session.beginReady();session.paused=false;lastTime=performance.now();world.blocked=true;}
  }
  function beginCountdown(){if(!session?.active||session.phase!=='ready')return;session.paused=false;session.readyRemaining=2;lastTime=performance.now();world.blocked=true;announce('Get ready. Combat resumes after two seconds.');}
  function showLevelComplete(){
    const final=session.levelIndex===D.levels.length-1,nextLevel=D.levels[session.levelIndex+1];
    openModal('levelComplete',shell('AREA CLEARED · TIMER PAUSED',final?'You broke the spell of all five realms.':session.level.name+' is clear.',`<div class="level-victory">✦</div><p class="modal-intro">${session.level.enemies} enemies defeated. ${session.level.enemies} questions faced. You decide what comes next.</p>${final?'<p class="modal-intro">The Crown of Temptation has fallen. Carry the lesson beyond the screen.</p>':`<div class="next-area-card" style="--area-color:${nextLevel.color}"><span class="eyebrow">NEXT · ${esc(nextLevel.difficulty.toUpperCase())}</span><h3>${esc(nextLevel.name)}</h3><p>${esc(nextLevel.tagline)}</p><div>${nextLevel.enemies} enemies · ${nextLevel.hp} base HP · stronger, faster attacks</div></div><p class="modal-intro">Continuing teleports you to the new area and restores combat health. Your remaining time and quiz chances carry over.</p>`}<div class="modal-actions">${final?'<button class="primary" data-action="victory">Finish adventure & reflect →</button>':'<button class="primary" data-action="next-level">Continue to next area →</button>'}<button class="secondary" data-action="end">Quit & keep my rewards</button></div>`,false));
  }
  function nextLevel(){if(!session?.continueLevel())return;world.loadLevel(session.level);dismissModal();world.blocked=true;updateUI();toast(session.level.name+' · '+session.level.difficulty);$('readyOverlay').hidden=false;$('readyNumber').textContent='2';}

  function showShop(){openModal('shop',shell('SPEND WITH INTENTION','A little mystery. A real choice.',`<p class="modal-intro">Your balance: <strong>${profile.coins.toLocaleString()} earned gold</strong>. Each chest contains one random hero. All heroes within a tier are equally likely.</p><div class="shop-grid">${D.chests.map(chest=>`<article class="chest-card" style="--glow:${chest.color}33"><div class="chest-art ${chest.style}" aria-hidden="true"></div><h3>${chest.name}</h3><p>${chest.description}</p><div class="odds">${D.tiers.map((tier,i)=>`<div><span>${tier}</span><b>${chest.odds[i]}%</b></div>`).join('')}</div><button class="buy-button" data-chest="${chest.id}" ${profile.coins<chest.cost?'disabled':''}><i class="coin"></i> ${chest.cost} gold${profile.coins<chest.cost?' · need '+(chest.cost-profile.coins)+' more':''}</button></article>`).join('')}</div><div class="modal-note">Duplicates return 25% of the chest price. Each opening is independent; a previous loss never guarantees a future win. Coins have no cash value, cannot be bought, and cannot be cashed out. You can also choose to save them.${session?.active?'<br><strong>The action and timer are paused while you browse.</strong>':''}</div>`));}
  function purchase(id){const chest=D.chests.find(c=>c.id===id);const result=E.buyChest(profile,chest);if(!result)return;if(session?.active){session.spent+=result.cost;session.openings++;if(result.duplicate)session.duplicates++;}save();updateUI();tone();const h=result.hero;openModal('reveal',shell(result.duplicate?'A FAMILIAR FACE':'YOUR DISCOVERY',result.duplicate?'Some paths cross again.':'A new companion for the journey.',`<div class="reveal" style="--aura:${h.color};--tint:${h.color}44"><div class="reveal-orbit"><div class="sprite" style="${spriteStyle(h)}"></div></div><span class="rarity">${h.rarity} · ${result.duplicate?'DUPLICATE':'NEW HERO'}</span><h3>${h.name}</h3><p>${h.role}<br>${h.hp} health · ${h.damage} attack damage</p><p>${result.duplicate?`Already in your collection. ${result.refund} gold returned.`:'Added to your collection. Equip this hero whenever you like.'}</p><div class="modal-actions" style="justify-content:center"><button class="primary" data-equip="${h.id}">Equip hero <span>→</span></button><button class="secondary" data-action="shop">Back to shop</button></div></div><div class="modal-note">This was one random outcome. Higher rarity does not measure your knowledge, effort, or worth.</div>`));}
  function showHeroes(){openModal('heroes',shell('THE COMPANIONS OF LUMEN','Different gifts. The same potential.',`<p class="modal-intro">${profile.owned.length} of 8 heroes discovered · two per rarity. Damage determines how quickly your attacks defeat enemies. Every hero gets <strong>five chances</strong>.</p><div class="collection-grid">${D.heroes.map(h=>{const owned=profile.owned.includes(h.id);return `<article class="hero-card ${owned?'':'locked'}" style="--aura:${h.color};--tint:${h.color}22"><span class="rarity">${h.rarity}</span><div class="sprite" style="${spriteStyle(h)}"></div><h3>${h.name}</h3><p>${h.hp} HP · ${h.damage} damage<br>${h.role}</p><button data-equip="${h.id}" ${!owned||h.id===profile.selected?'disabled':''}>${!owned?'Undiscovered':h.id===profile.selected?'✓ Equipped':'Equip hero'}</button></article>`;}).join('')}</div><div class="modal-note">Rare: blue aura · Epic: violet aura · Legend: gold aura · Mythic: ember aura.<br>Equipping preserves your current health percentage and quiz chances. Two Rare heroes are yours from the start.${profile.items.includes('wisdom-compass')?'<br>✧ Wisdom Compass unlocked — a cosmetic light follows your hero.':''}</div>`));}
  function equip(id){if(!profile.owned.includes(id))return;profile.selected=id;save();const h=selectedHero();if(session)session.equip(h);updateUI();toast(`${h.name} is ready.`);showHeroes();}
  function showLeaderboard(){const entries=[{name:'Player 2',score:2400,note:'Simulated rival · fixed benchmark'},{name:'Moss & Moon',score:1450,note:'Simulated rival'},{name:'Little Lantern',score:850,note:'Simulated rival'},{name:profile.name||'You, the explorer',score:session?session.score:profile.best,note:session?'You · this expedition':'You · personal best',you:true}].sort((a,b)=>b.score-a.score);openModal('leaderboard',shell('REALM RANKINGS · SIMULATED RIVALS','Let progress be your measure.',`<p class="modal-intro">Player 2 starts at the top with <strong>2,400 points</strong>. These rivals are fictional, fixed benchmarks. Only your own results are saved on this device.</p><table class="rank-table"><thead><tr><th>RANK</th><th>ADVENTURER</th><th>SCORE</th></tr></thead><tbody>${entries.map((e,i)=>`<tr><td>${String(i+1).padStart(2,'0')}</td><td>${esc(e.name)}${e.you?' ✦':''}<small>${e.note}</small></td><td>${e.score.toLocaleString()}</td></tr>`).join('')}</tbody></table><div class="modal-note"><strong>Earn a Rare Wisdom Compass at 1,200 points.</strong> This is a guaranteed cosmetic reward for learning, independent of your rank and chest results. ${profile.items.includes('wisdom-compass')?'✓ Already unlocked.':'Awarded when your expedition ends.'}</div><p class="modal-intro" style="margin-top:18px">Your personal best: <strong>${Math.max(profile.best,session?.score||0).toLocaleString()}</strong>. Notice whether seeing another score makes you want to spend. You can choose to keep learning instead.</p>${profile.history.length?`<span class="eyebrow">RECENT EXPEDITIONS ON THIS DEVICE</span><table class="rank-table"><tbody>${profile.history.slice(0,4).map(h=>`<tr><td>${h.minutes} min expedition</td><td>${h.correct}/${h.answered} correct</td><td>${h.score.toLocaleString()}</td></tr>`).join('')}</tbody></table>`:''}`));}
  function reflectionMarkup(){return `<div class="reflection-copy"><h3>Chance is not a promise.</h3><p>A more expensive chest changes the probabilities. It does not guarantee the hero you want. A duplicate or a long unlucky streak does not make the next independent opening “due” to win.</p><h3>Your gold. Your choice.</h3><p>Mystery rewards and leaderboards can make another purchase feel urgent. Stop, notice that feeling, and decide whether the reward is worth the cost. Saving your coins is a valid choice. You never need to chase a loss.</p><h3>A value to carry beyond the game.</h3><p>Islam teaches avoiding gambling (maysir), as described in <a href="https://quran.com/5/90" target="_blank" rel="noopener noreferrer">Qur’an 5:90</a>. Protecting what we have, acting thoughtfully, and caring for others are part of the lesson. Paid random-reward systems deserve careful scrutiny when money or items of real value are at stake.</p><p>This game is a classroom simulation using earned fictional coins, with no payments, trading, or cash-out. It does not claim that every random game reward has the same religious ruling. Discuss real examples with your teacher.</p></div>`;}
  function showReflection(){openModal('reflection',shell('THE LESSON BEHIND THE ADVENTURE','Take the wisdom with you.',reflectionMarkup()));}
  function pause(){if(!session?.active||modalKind==='quiz'||modalKind==='levelComplete')return;session.paused=true;world.keys.clear();openModal('pause',shell('TAKE YOUR TIME','The woods can wait.',`<p class="modal-intro">Combat and the session clock are paused. Resume when you are ready.</p><div class="modal-actions"><button class="primary" data-action="resume">Resume adventure <span>→</span></button><button class="secondary" data-action="end">Finish this expedition</button></div>`));}
  function finish(reason){if(!session||finished)return;finished=true;session.end(reason||session.reason);world.active=true;world.blocked=true;world.keys.clear();profile.best=Math.max(profile.best,session.score);const reward=session.score>=1200&&!profile.items.includes('wisdom-compass');if(reward)profile.items.push('wisdom-compass');profile.history.unshift({score:session.score,correct:session.correct,answered:session.answered,minutes:session.minutes,levels:session.levelsCleared});profile.history=profile.history.slice(0,8);save();$('sessionBadge').textContent='COMPLETE';$('adventureStatus').textContent='A little wiser than before';$('expeditionTitle').textContent='Look how far you came.';$('expeditionDescription').textContent='Your next chapter is waiting whenever you are.';$('questionButton').disabled=true;$('questionButton').textContent='Expedition complete';$('pauseButton').hidden=true;$('interactPrompt').hidden=true;$('readyOverlay').hidden=true;$('touchControls').hidden=true;$('playerName').disabled=false;document.querySelectorAll('[data-duration]').forEach(b=>b.disabled=false);$('welcome').hidden=false;$('welcome').innerHTML='<span class="chapter-tag">YOUR NEXT CHAPTER</span><h2>Keep the wisdom.<br><em>Begin again.</em></h2><p>Your collection and earned gold stay with you.</p><button class="primary" id="startAgain">New adventure <span>→</span></button><small>Choose 5 or 10 minutes of active gameplay.</small>';$('startAgain').onclick=start;updateUI();const accuracy=session.answered?Math.round(session.correct/session.answered*100):0;openModal('results',shell('EXPEDITION COMPLETE',session.reason==='victory'?'All five realms. One wiser adventurer.':session.reason==='chances'?'Five chances. Many discoveries.':'A little wiser than before.',`<p class="modal-intro">${esc(profile.name)}, ${({time:'your active gameplay time is complete',chances:'your five quiz chances are used',health:'your combat health reached zero',victory:'you completed all five areas',choice:'you chose to end this expedition'}[session.reason])}. What you learned stays with you.</p><div class="results-stats"><div><strong>${session.score.toLocaleString()}</strong><span>KNOWLEDGE SCORE</span></div><div><strong>${accuracy}%</strong><span>${session.correct} / ${session.answered} CORRECT</span></div><div><strong>${session.earned}</strong><span>GOLD EARNED</span></div></div><p class="modal-intro">Best streak: <strong>${session.bestStreak}</strong> · Enemies defeated: <strong>${session.defeated}</strong> · Areas cleared: <strong>${session.levelsCleared}/5</strong><br>Chest purchases: ${session.openings} · Gold spent: ${session.spent} · Duplicates: ${session.duplicates}</p>${reward?'<div class="modal-note">✧ <strong>Rare Wisdom Compass unlocked!</strong> You earned it by reaching 1,200 points. No luck required.</div>':''}${reflectionMarkup()}<div class="modal-actions"><button class="primary" data-action="new">Choose your next adventure <span>→</span></button><button class="secondary" data-action="leaderboard">View rankings</button></div>${!storageAvailable?'<div class="modal-note">Browser storage is unavailable. Progress is kept only while this page remains open.</div>':''}`));tone();}
  function showHelp(){openModal('help',shell('YOUR FIELD GUIDE','Fight the enemy. Question the temptation.',`<div class="settings-list"><div><b>Move:</b> A / D or ← / → to walk. Hold Shift to run. Space, W, or ↑ to jump. Mobile controls are on the scene.</div><div><b>Attack:</b> Move close and tap or hold J (E also works), or use the Attack button. Your hero’s damage affects each strike. Enemies show a glowing ! before attacking; move or jump away.</div><div><b>Question after battle:</b> Every defeated enemy opens exactly one casino/gambling question. The world and clock freeze. After answering, feedback displays for two seconds before play resumes automatically. “Keep reading” pauses that countdown; Resume starts a fresh two seconds.</div><div><b>Health & chances:</b> Enemy hits drain combat health. A correct answer heals up to 15 HP and earns 40–60 gold. A wrong answer uses one of five quiz chances. Zero health, zero chances, or zero active time ends the run.</div><div><b>Five areas:</b> Lantern Meadow (Super Easy), Mirage Bazaar (Easy), Velvet Casino (Mid), House of Mirrors (Hard), and Crown of Temptation (Extreme). Clear the enemies and questions, then quit or teleport onward. A new area restores health; time and quiz chances carry over.</div><div><b>Time:</b> Choose 5 or 10 minutes of active gameplay. Questions, feedback, countdowns, menus, and level decisions do not use this time. Switching tabs pauses automatically.</div><div><b>Questions:</b> Slots, roulette, casino offers, chasing losses, and Islamic values. Every area includes an Islamic-values question with a source link.</div><div><b>Collection:</b> Eight heroes, three chests, visible odds, and a 25% duplicate refund. Only earned fictional coins are used. Your collection saves in this browser; active runs do not resume after reload.</div></div><div class="modal-actions"><button class="primary" data-action="close">Ready to explore →</button></div>`));}

  $('modalContent').addEventListener('click',event=>{
    const button=event.target.closest('button');if(!button||button.disabled)return;
    if(button.dataset.answer!==undefined){answer(Number(button.dataset.answer));return;}
    if(button.dataset.chest){purchase(button.dataset.chest);return;}
    if(button.dataset.equip){equip(button.dataset.equip);return;}
    switch(button.dataset.action){
      case'close':case'resume':closeModal();break;
      case'continue':if(!session.active)finish(session.reason);else beginCountdown();break;
      case'read-more':if(session?.phase==='ready'){if(session.paused)beginCountdown();else session.paused=true;}break;
      case'next-level':nextLevel();break;
      case'victory':finish('victory');break;
      case'shop':showShop();break;
      case'leaderboard':showLeaderboard();break;
      case'end':finish('choice');break;
      case'new':closeModal();$('playerName').focus({preventScroll:true});toast('Choose a duration, then begin again.');break;
    }
  });
  function attack(){if(!session?.active){toast('Begin your adventure first.');return;}if(world.attack())updateUI();}
  world.onQuestion=showQuiz;world.onDamage=()=>updateUI();
  $('startButton').onclick=start;$('navPlay').onclick=()=>{if($('modal').open)closeModal();$('world').focus({preventScroll:true});};$('brand').onclick=event=>{event.preventDefault();if($('modal').open)closeModal();};
  $('shopButton').onclick=showShop;$('navHeroes').onclick=showHeroes;$('viewHeroes').onclick=showHeroes;$('navLeaderboard').onclick=showLeaderboard;$('rankingsButton').onclick=showLeaderboard;$('helpButton').onclick=showHelp;$('reflectionButton').onclick=showReflection;$('pauseButton').onclick=pause;$('interactButton').onclick=attack;$('questionButton').onclick=attack;
  $('soundButton').onclick=()=>{sound=!sound;$('soundButton').classList.toggle('on',sound);$('soundButton').setAttribute('aria-label',sound?'Mute sound':'Enable sound');$('soundButton').title=sound?'Mute sound':'Enable sound';if(sound)tone();};
  $('dayButton').onclick=()=>{const modes=['auto','day','night'];world.mode=modes[(modes.indexOf(world.mode)+1)%3];$('dayButton').innerHTML=(world.mode==='night'?'☾':'☀')+' <span>'+(world.mode==='auto'?'Auto cycle':world.mode==='day'?'Daylight':'Moonlight')+'</span>';};
  function inputKey(event){if(event.code==='Space')return 'Space';return event.key.length===1?event.key.toLowerCase():event.key;}
  window.addEventListener('keydown',event=>{
    if(event.target.matches('input,textarea,select'))return;const key=inputKey(event);
    if($('modal').open){if(modalKind==='quiz'&&['1','2','3','4'].includes(key)){event.preventDefault();answer(Number(key)-1);}return;}
    if(!session?.active)return;
    if(['ArrowLeft','ArrowRight','ArrowUp','Space','a','d','w','Shift','e','j','Escape'].includes(key)){event.preventDefault();if(key==='Escape')pause();else if(session.canFight){world.keys.add(key);if((key==='j'||key==='e')&&!event.repeat)attack();}}
  });
  window.addEventListener('keyup',event=>world.keys.delete(inputKey(event)));
  window.addEventListener('blur',()=>world.keys.clear());
  document.addEventListener('visibilitychange',()=>{world.keys.clear();if(document.hidden&&session?.active){session.paused=true;if(!$('modal').open)pause();}});
  document.querySelectorAll('[data-control]').forEach(button=>{
    const key=button.dataset.control;button.addEventListener('pointerdown',event=>{event.preventDefault();if(!session?.canFight)return;button.setPointerCapture(event.pointerId);world.keys.add(key);if(key==='j')attack();});
    for(const type of ['pointerup','pointercancel','lostpointercapture'])button.addEventListener(type,()=>world.keys.delete(key));
  });
  function loop(now){
    const elapsed=(now-lastTime)/1000;lastTime=now;
    if(session){
      if(session.active){
        session.tick(elapsed);
        if(!session.active)finish(session.reason);
        else if(session.phase==='levelComplete'&&modalKind!=='levelComplete')showLevelComplete();
        else if(session.phase==='combat'&&modalKind==='quiz'&&session.resolved)dismissModal();
        world.blocked=!session.canFight||$('modal').open;
        const ready=session.phase==='ready';$('readyOverlay').hidden=!ready||$('modal').open;if(ready){$('readyNumber').textContent=Math.ceil(session.readyRemaining);if($('returnCountdown')){$('returnCountdown').textContent=session.paused?'Countdown paused':'Returning in '+Math.ceil(session.readyRemaining)+' seconds…';const readButton=$('modalContent').querySelector('[data-action="read-more"]');if(readButton)readButton.textContent=session.paused?'Resume · 2 seconds':'Keep reading';}}
        const target=world.nearestEnemy,inRange=target&&Math.abs(target.x-world.player.x)<132;
        $('interactPrompt').hidden=!inRange||!session.canFight||$('modal').open;
        $('questionButton').disabled=!session.canFight;$('questionButton').textContent=session.canFight?'Attack enemy · J →':session.phase==='ready'?'Get ready…':'Action & timer paused';
        if(session.canFight&&target)$('worldCaption').textContent=inRange?'Hold J to attack · jump when you see !':target.x>world.player.x?'Next enemy → · '+Math.round(Math.abs(target.x-world.player.x))+' steps':'← Next enemy · '+Math.round(Math.abs(target.x-world.player.x))+' steps';
        $('adventureStatus').textContent=session.canFight?session.level.difficulty+' · Battle in progress':ready?'Get ready · timer paused':'Action & timer paused';
        updateUI();
      }else if(!finished&&session.reason!=='chances')finish(session.reason);
    }
    $('worldTime').textContent=(world.night>.65?'Moonlight':world.night>.3?'Twilight':'Golden hour')+' · '+(session?session.level.difficulty:'Super Easy');
    requestAnimationFrame(loop);
  }
  $('playerName').value=profile.name;renderTeasers();updateUI();requestAnimationFrame(loop);
  if(!storageAvailable)toast('Storage unavailable: progress stays in this open page only.');
  window.Lumen={get session(){return session;},get profile(){return profile;},world};
})();
